<script setup lang="ts">
import {ref} from 'vue';
import {uid,newArrangement,colors,validateCourse,collisions,type ManagedCourse,type Semester} from '../domain/schedule';
const props=defineProps<{course?:ManagedCourse;semester:Semester;existing:ManagedCourse[]}>();
const emit=defineEmits<{save:[course:ManagedCourse];cancel:[]}>();
const draft=ref<ManagedCourse>(props.course?JSON.parse(JSON.stringify(props.course)):{id:uid(),semesterId:props.semester.id,name:'',teacher:'',color:'blue',notes:'',arrangements:[newArrangement(props.semester.weekCount)]});
const error=ref(''),confirmed=ref(false),removeId=ref('');
function save(){error.value='';try{validateCourse(draft.value,props.semester);const p=collisions(draft.value,props.existing);if(p.some(x=>x.kind==='duplicate'))throw Error('存在完全重复的上课安排，请修改或删除重复项');if(p.length&&!confirmed.value)throw Error('存在时间冲突：'+p.map(x=>x.message).join('；')+'。如属实，请勾选保留冲突后保存');emit('save',JSON.parse(JSON.stringify(draft.value)))}catch(e){error.value=(e as Error).message}}
</script>
<template><form class="course-editor" @submit.prevent="save" @input="($event.target as HTMLInputElement).type!=='checkbox'&&(confirmed=false)"><h3>{{course?'编辑课程':'添加课程'}}</h3><label class="form-label">课程名称 *<input v-model="draft.name" maxlength="150" required/></label><div class="form-grid"><label class="form-label">教师<input v-model="draft.teacher" maxlength="100"/></label><label class="form-label">课程颜色<select v-model="draft.color"><option v-for="(c,i) in colors" :key="c" :value="c">{{['蓝灰','淡紫','青绿','暖杏','玫瑰'][i]}}</option></select></label></div><label class="form-label">备注<textarea v-model="draft.notes" rows="2" maxlength="2000"/></label>
<fieldset v-for="(a,i) in draft.arrangements" :key="a.id" class="arrangement"><legend>上课安排 {{i+1}}</legend><div class="form-grid"><label class="form-label">星期<select v-model.number="a.day"><option v-for="d in 7" :key="d" :value="d">星期{{['一','二','三','四','五','六','日'][d-1]}}</option></select></label><label class="form-label">教室<input v-model="a.room" maxlength="150"/></label><label class="form-label">开始节次（可空）<input v-model.number="a.startPeriod" type="number" min="1" max="24" @change="a.startPeriod=a.startPeriod||null"/></label><label class="form-label">结束节次（可空）<input v-model.number="a.endPeriod" type="number" min="1" max="24" @change="a.endPeriod=a.endPeriod||null"/></label><label class="form-label">开始时间 *<input v-model="a.start" type="time" required/></label><label class="form-label">结束时间 *<input v-model="a.end" type="time" required/></label><label class="form-label">开始教学周<input v-model.number="a.startWeek" type="number" min="1" :max="semester.weekCount" required/></label><label class="form-label">结束教学周<input v-model.number="a.endWeek" type="number" min="1" :max="semester.weekCount" required/></label></div><label class="form-label">教学周规则<select v-model="a.rule"><option value="all">每周</option><option value="odd">单周</option><option value="even">双周</option><option value="custom">自定义周</option></select></label><label v-if="a.rule==='custom'" class="form-label">自定义周（逗号分隔）<input :value="a.customWeeks.join(',')" @input="a.customWeeks=($event.target as HTMLInputElement).value.split(/[,，、]/).map(Number)" placeholder="1,3,5"/></label><template v-if="draft.arrangements.length>1"><button v-if="removeId!==a.id" type="button" class="text-button danger" @click="removeId=a.id">删除这个安排</button><div v-else class="inline-note">确认删除本安排？<button type="button" class="text-button danger" @click="draft.arrangements.splice(i,1);removeId=''">确认删除</button><button type="button" class="text-button" @click="removeId=''">取消</button></div></template></fieldset>
<button type="button" class="secondary full" @click="draft.arrangements.push(newArrangement(semester.weekCount))">＋ 添加另一个上课安排</button><p v-if="error" role="alert" class="form-error">{{error}}</p><label class="check-line"><input v-model="confirmed" type="checkbox"/>已核对，允许保留时间冲突</label><div class="modal-actions"><button type="button" class="secondary" @click="emit('cancel')">取消</button><button class="primary" type="submit">保存课程</button></div></form></template>
